<?php
declare(strict_types=1);
require_once __DIR__ . '/includes/config.php';
require_once __DIR__ . '/includes/auth.php';
require_login();
function projectEscape(mixed $value): string { return htmlspecialchars((string)($value ?? ''), ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'); }
$statuses = ['planning'=>'Planning','in_progress'=>'In progress','review'=>'In review','completed'=>'Completed'];
$error = ''; $success = '';
$clients = $pdo->query('SELECT id, name, company FROM clients ORDER BY name')->fetchAll();
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    verify_csrf_token();
    $action = (string)($_POST['action'] ?? '');
    $id = filter_var($_POST['id'] ?? null, FILTER_VALIDATE_INT);
    if ($action === 'delete') {
        if (!$id || $id < 1) $error = 'Invalid project ID.';
        else { $stmt=$pdo->prepare('DELETE FROM projects WHERE id=:id'); $stmt->execute(['id'=>$id]); header('Location: projects.php?deleted=1'); exit; }
    } elseif (in_array($action, ['create','update'], true)) {
        $name=trim((string)($_POST['name']??'')); $description=trim((string)($_POST['description']??''));
        $clientRaw=trim((string)($_POST['client_id']??'')); $budgetRaw=trim((string)($_POST['budget']??'0'));
        $deadline=trim((string)($_POST['deadline']??'')); $status=(string)($_POST['status']??'planning'); $clientId=null;
        if ($clientRaw !== '') { $valid=filter_var($clientRaw,FILTER_VALIDATE_INT); if (!$valid || $valid<1) $error='Select a valid client.'; else { $check=$pdo->prepare('SELECT id FROM clients WHERE id=:id'); $check->execute(['id'=>$valid]); if (!$check->fetchColumn()) $error='Selected client was not found.'; else $clientId=$valid; } }
        if (!$error && ($name==='' || mb_strlen($name)>150)) $error='Project name is required (maximum 150 characters).';
        if (!$error && (!is_numeric($budgetRaw) || (float)$budgetRaw<0 || (float)$budgetRaw>9999999999.99)) $error='Enter a valid budget.';
        if (!$error && !isset($statuses[$status])) $error='Select a valid status.';
        if (!$error && $deadline!=='') { $date=DateTime::createFromFormat('!Y-m-d',$deadline); if (!$date || $date->format('Y-m-d')!==$deadline) $error='Enter a valid deadline.'; }
        if (!$error) {
            if ($action==='create') { $stmt=$pdo->prepare('INSERT INTO projects(client_id,name,description,budget,status,progress,deadline) VALUES(:client_id,:name,:description,:budget,:status,:progress,:deadline)'); $stmt->execute(['client_id'=>$clientId,'name'=>$name,'description'=>$description!==''?$description:null,'budget'=>(float)$budgetRaw,'status'=>$status,'progress'=>$status==='completed'?100:0,'deadline'=>$deadline!==''?$deadline:null]); header('Location: projects.php?created=1'); exit; }
            if (!$id || $id<1) $error='Invalid project ID.'; else { $stmt=$pdo->prepare('UPDATE projects SET client_id=:client_id,name=:name,description=:description,budget=:budget,status=:status,progress=:progress,deadline=:deadline WHERE id=:id'); $stmt->execute(['client_id'=>$clientId,'name'=>$name,'description'=>$description!==''?$description:null,'budget'=>(float)$budgetRaw,'status'=>$status,'progress'=>$status==='completed'?100:0,'deadline'=>$deadline!==''?$deadline:null,'id'=>$id]); header('Location: projects.php?updated=1'); exit; }
        }
    }
}
if (isset($_GET['created'])) $success='Project created.'; elseif(isset($_GET['updated'])) $success='Project updated.'; elseif(isset($_GET['deleted'])) $success='Project deleted.';
$search=trim((string)($_GET['q']??'')); $filter=(string)($_GET['status']??''); if(!isset($statuses[$filter])) $filter='';
$sql='SELECT p.*,c.name AS client_name,c.company AS client_company FROM projects p LEFT JOIN clients c ON c.id=p.client_id WHERE (p.name LIKE :q1 OR COALESCE(c.name,\'\') LIKE :q2 OR COALESCE(c.company,\'\') LIKE :q3)';
$params=['q1'=>'%'.$search.'%','q2'=>'%'.$search.'%','q3'=>'%'.$search.'%']; if($filter!==''){ $sql.=' AND p.status=:status'; $params['status']=$filter; } $sql.=' ORDER BY p.created_at DESC,p.id DESC';
$stmt=$pdo->prepare($sql); $stmt->execute($params); $projects=$stmt->fetchAll();
$edit=null; $editId=filter_var($_GET['edit']??null,FILTER_VALIDATE_INT); if($editId && $editId>0){$stmt=$pdo->prepare('SELECT * FROM projects WHERE id=:id');$stmt->execute(['id'=>$editId]);$edit=$stmt->fetch()?:null;}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Projects | WebAgency CRM</title><link rel="stylesheet" href="assets/css/style.css"></head><body><div class="app-shell"><aside class="sidebar"><a class="brand" href="index.php">WebAgency <b>CRM</b></a><nav class="nav"><a class="nav-link" href="index.php">Dashboard</a><a class="nav-link" href="clients.php">Clients</a><a class="nav-link" href="projects.php">Projects</a><a class="nav-link" href="tasks.php">Tasks</a></nav><div class="sidebar-bottom"><a class="nav-link" href="logout.php">Log out</a></div></aside><main class="main-content"><header class="topbar"><div><p class="eyebrow">WORKSPACE</p><h1>Projects</h1></div></header>
<?php if($error!==''): ?><div class="alert error"><?=projectEscape($error)?></div><?php endif; ?><?php if($success!==''): ?><div class="alert success"><?=projectEscape($success)?></div><?php endif; ?>
<section class="panel"><div class="panel-heading"><h2><?=$edit?'Edit project':'Create project'?></h2></div><form method="post" class="project-form"><input type="hidden" name="csrf_token" value="<?=projectEscape(csrf_token())?>"><input type="hidden" name="action" value="<?=$edit?'update':'create'?>"><?php if($edit): ?><input type="hidden" name="id" value="<?=(int)$edit['id']?>"><?php endif; ?><label>Project name<input name="name" maxlength="150" required value="<?=projectEscape($edit['name']??'')?>"></label><label>Client<select name="client_id"><option value="">No client</option><?php foreach($clients as $client): ?><option value="<?=(int)$client['id']?>" <?=((string)($edit['client_id']??'')===(string)$client['id'])?'selected':''?>><?=projectEscape($client['name'])?><?=!empty($client['company'])?' — '.projectEscape($client['company']):''?></option><?php endforeach; ?></select></label><label>Budget<input type="number" min="0" step="0.01" name="budget" value="<?=projectEscape($edit['budget']??'0')?>" required></label><label>Deadline<input type="date" name="deadline" value="<?=projectEscape($edit['deadline']??'')?>"></label><label>Status<select name="status"><?php foreach($statuses as $key=>$label): ?><option value="<?=projectEscape($key)?>" <?=($edit['status']??'planning')===$key?'selected':''?>><?=projectEscape($label)?></option><?php endforeach; ?></select></label><label>Description<textarea name="description" rows="3"><?=projectEscape($edit['description']??'')?></textarea></label><div class="modal-actions"><button class="primary-button" type="submit"><?=$edit?'Save changes':'Create project'?></button><?php if($edit): ?><a class="secondary-button" href="projects.php">Cancel</a><?php endif; ?></div></form></section>
<section class="panel"><div class="panel-heading"><h2>Project list (<?=count($projects)?>)</h2></div><form method="get" class="project-form"><label>Search<input type="search" name="q" value="<?=projectEscape($search)?>" placeholder="Project, client or company"></label><label>Status<select name="status"><option value="">All statuses</option><?php foreach($statuses as $key=>$label): ?><option value="<?=projectEscape($key)?>" <?=$filter===$key?'selected':''?>><?=projectEscape($label)?></option><?php endforeach; ?></select></label><button class="primary-button" type="submit">Filter</button></form><div class="table-wrap"><table><thead><tr><th>Project</th><th>Client</th><th>Status</th><th>Progress</th><th>Budget</th><th>Deadline</th><th>Actions</th></tr></thead><tbody><?php foreach($projects as $p): ?><tr><td><?=projectEscape($p['name'])?></td><td><?=projectEscape($p['client_name']??'—')?></td><td><span class="badge <?=projectEscape($p['status'])?>"><?=projectEscape($statuses[$p['status']]??$p['status'])?></span></td><td><?=(int)$p['progress']?>%</td><td><?=number_format((float)$p['budget'],2)?></td><td><?=projectEscape($p['deadline']??'—')?></td><td><a class="secondary-button" href="projects.php?edit=<?=(int)$p['id']?>">Edit</a><form method="post" onsubmit="return confirm('Delete this project?')"><input type="hidden" name="csrf_token" value="<?=projectEscape(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$p['id']?>"><button class="secondary-button" type="submit">Delete</button></form></td></tr><?php endforeach; ?><?php if(!$projects): ?><tr><td colspan="7">No projects found.</td></tr><?php endif; ?></tbody></table></div></section><footer class="footer">WebAgency CRM &copy; <?=date('Y')?></footer></main></div></body></html>
